451	                return info;
452	            }
453	            info.state = attempt.state;
454	            info.message = attempt.message;
455	        }
456	        return info;
457	    }
458	    info.provider = "bambu";
459	    info.device_id = printer->device_id;
460	    auto* devices = wxGetApp().getDeviceManager();
461	    auto* agent = wxGetApp().getAgent();
462	    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
463	    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
464	        info.state = "unavailable";
465	        info.needs_network_plugin = true;
466	        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not installed or not turned on. "
467	                       "The person can already prepare prints for this printer without it.";
468	        return info;
469	    }
470	    if (!devices || !agent) {
471	        info.state = "unavailable";
472	        info.message = "Connecting is not available right now. The person can already prepare prints for this printer.";
473	        return info;
474	    }
475	    // The local list is what has announced itself on this network; the cloud
476	    // list is the person's account, wherever those printers are.
477	    const auto nearby = devices->get_local_machinelist();
478	    auto candidates = nearby;
479	    for (const auto& entry : devices->get_my_cloud_machine_list())
480	        candidates[entry.first] = entry.second;
481	    for (const auto& [id, machine] : candidates) {
482	        if (!machine || machine->printer_type != model->device_model_id)
483	            continue;
484	        if (!info.device_id.empty() && id != info.device_id)
485	            continue;
486	        const bool used_elsewhere = std::any_of(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
487	            return p.name != name && p.device_id == id;
488	        });
489	        if (!used_elsewhere && (!machine->is_lan_mode_printer() || machine->is_avaliable()))
490	            info.candidates.push_back({id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer(),
491	                                       nearby.find(id) == nearby.end()});
492	    }
493	    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
494	    // is_connected() alone is optimistic immediately after reset(). Require
495	    // actual parsed push data, and fresh LAN data for a LAN connection.
496	    const bool communicating = machine && has_recent_printer_data(*machine);
497	    const bool configured = has_verified_printer_connection(info.device_id);
498	    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
499	    if (info.state == "unknown")
500	        info.message = "Connection status is unknown. Check that the printer is on, then reconnect.";
501	    if (m_connection_attempt && m_connection_attempt->name == name) {
502	        const auto& attempt = *m_connection_attempt;
503	        if (info.device_id != attempt.device_id)
504	            throw std::logic_error("A connection attempt lost its saved printer association");
505	        const bool observed = communicating &&
506	            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
507	                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
508	        if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
509	            info.state = "failed";
510	            info.message = "The selected printer changed. Select this printer again to reconnect.";
511	        } else if (observed) {
512	            info.state = "verified";
513	            m_connection_attempt.reset();
514	        } else if (machine == nullptr) {
515	            info.state = "failed";
516	            info.message = "The printer is no longer available. Refresh the printer list and try again.";
517	        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
518	            info.state = "failed";
519	            info.message = "The printer did not respond. Check that it is on the network and try again.";
520	        } else {
521	            info.state = "connecting";
522	            info.message.clear();
523	        }
524	    }
525	    if (info.state == "verified")
526	        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
527	    if (communicating) {
528	        const auto* extruders = machine->GetExtderSystem();
529	        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
530	            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
531	    }
532	    return info;
