186	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
187	{
188	    // An attempt the last session left waiting -- its panel closed meanwhile
189	    // -- is dropped before this session can read, and save, its outcome.
190	    abandon_connection();
