217	        // network are worth naming. Both sit under the opening, where the
218	        // person is deciding what to say.
219	        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
220	        if (!m_network.empty()) {
221	            json found = json::array();
222	            for (const DiscoveredPrinter& printer : m_network)
223	                found.push_back(json{{"name", printer.name}, {"serial", printer.stable_id}, {"online", printer.connected}});
224	            m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""},
