470	std::string PrinterConversation::search_text() const
471	{
472	    if (!m_search)
473	        return "No network search has run yet in this conversation; printer_connection_status starts it.";
474	    const std::string seconds =
475	        std::to_string(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - m_search->started).count());
476	    if (m_search->port != DiscoveryPort::Ours)
477	        return m_search->port == DiscoveryPort::Taken ? kPortTaken : kNotListening;
478	    if (!m_search->said_none && !m_search->found)
479	        return "The network search started " + seconds + " seconds ago and has found no printer of this model yet. The app posts a note "
480	               "when one appears, or after about " + std::to_string(kSearchWait.count()) + " seconds with none.";
481	    return "The network search has listened for " + seconds + " seconds and has found no printer of this model in LAN mode." +
482	           (m_search->found ? "" : " The app posts a note if one appears.");
483	}
